def normalizar_texto(valor) -> str:
    texto = str(valor or "").strip().lower()
    texto = "".join(c for c in unicodedata.normalize("NFD", texto) if unicodedata.category(c) != "Mn")
    return re.sub(r"\s+", " ", texto).strip()


def causa_workbook_2026(registro: dict) -> str:
    motivo = normalizar_texto(registro.get("motivo")).upper()
    if not motivo:
        return "SEM_CAUSA_ESTRUTURADA"
    return MOTIVO_CAUSA_2026.get(motivo, "OUTROS_VALIDAR")


def categoria_workbook_2026(registro: dict) -> str:
    status = normalizar_texto(registro.get("status")).upper()
    if status in {"", "80", "NAN", "NONE", "#N/A", "N/A", "NAO INFORMADO"}:
        return "NAO_CLASSIFICADO"
    if status == "CARRIER": return "CARRIER"
    if status == "TK": return "TK"
    if status == "NACIONAL": return "NACIONAL"
    if status == "SEM CONTATO": return "SEM_CONTATO"
    if status == "USADO CONCORRENTE": return "USADO_CONCORRENTE"
    if status == "USADO CARRIER": return "USADO_CARRIER"
    return "OUTROS"


def extrair_observacao_workbook(registro: dict) -> str:
    ocorrencia = str(registro.get("ocorrencia") or "")
    match = re.search(r"(?:^|\n)OBSERVAÇÃO:\s*(.*?)(?=\n(?:PLANO AÇÃO 1|QUANDO|STATUS PLANO AÇÃO 1):|$)", ocorrencia, flags=re.S | re.I)
    if match:
        return match.group(1).strip()
    # Compatibilidade com registros canônicos que já contenham apenas a observação.
    if not any(rotulo in ocorrencia.upper() for rotulo in ("REPRESENTAÇÃO:", "PLANO AÇÃO 1:", "QUANDO:", "STATUS PLANO AÇÃO 1:")):
        return ocorrencia.strip()
    return ""


def temas_workbook_2026(registro: dict) -> list[str]:
    observacao = extrair_observacao_workbook(registro)
    if not observacao:
        return []
    digest = hashlib.sha1(normalizar_texto(observacao).encode("utf-8")).hexdigest()
    temas = [tema for tema, hashes in THEME_HASHES_2026.items() if digest in hashes]
    return temas or ["CONTEXTO_LIVRE"]
